if(path==='/api/profile'&&method==='PATCH'){const b=await body(req),p=parse(ctx.user.profile);if(b.name)required(trim(b.name,120),'Укажите ФИО',400);const next={...p};for(const key of ['theme','accent','avatar','motion','tutorial_done'])if(b[key]!==undefined)next[key]=b[key];if(b.photo!==undefined){required(b.photo===''||typeof b.photo==='string'&&b.photo.length<=700000&&/^data:image\/(png|jpeg|webp);base64,/.test(b.photo),'Недопустимое фото',400);next.photo=b.photo;}await run(env.DB,'UPDATE users SET name=?,profile=? WHERE id=?',trim(b.name,120)||ctx.user.name,JSON.stringify(next),ctx.user.id);return json({ok:true});}
